{
  "claims": [
    {
      "claim_id": "ISS-001",
      "claim_text": "Motor proteins such as kinesin and cytoplasmic dynein bind vesicles and move them along microtubules in an ATP-dependent manner.",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Eukaryotic intracellular vesicle transport; microtubule-based motility; motor protein families",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        },
        {
          "evidence_id": "E_3717dae1f63f",
          "location": "abstract",
          "quote": "Tau binds microtubules cooperatively to form cohesive envelopes, which are thought to control access to the microtubule lattice and regulate the activity of motor proteins and other MAPs."
        }
      ],
      "reason": "Sources state that kinesin and dynein motors use microtubules as tracks to transport cargo including organelles, but do not explicitly state that motor proteins bind vesicles or that movement is ATP-dependent. The ATP-dependence and vesicle-binding aspects are not entailed by the provided excerpts."
    },
    {
      "claim_id": "ISS-002",
      "claim_text": "Vesicles are cargo carriers that are actively transported along microtubule tracks by motor proteins, establishing causal motor dependence.",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Intracellular vesicle trafficking; active transport; cargo-motor-microtubule coupling",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        },
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "the normal distribution of kinesin-1 in the germline relies on TTLL5 . Next, two kinesin-1-dependent processes, the precise localization of Staufen and the fast, bidirectional ooplasmic streaming, depend on TTLL5 , too, suggesting a causative pathway."
        }
      ],
      "reason": "Sources support that microtubules are tracks for kinesin/dynein to transport cargos including organelles, and that some kinesin-1-dependent processes rely on microtubule modifications. However, vesicles are not explicitly named as the cargo in the quoted passages, and causal motor dependence for vesicle transport specifically is not directly established."
    },
    {
      "claim_id": "ISS-003",
      "claim_text": "Individual vesicles can be observed moving processively along microtubules during defined intervals, supporting temporal persistence semantics.",
      "entailment_status": "INSUFFICIENT_EVIDENCE",
      "biological_scope": "Single-vesicle tracking; processive motor movement; live-cell imaging of vesicle transport",
      "support": [],
      "reason": "No provided source excerpt describes single-vesicle tracking, processive movement of individual vesicles along microtubules, or defined temporal intervals of observation. The abstracts discuss lysosome transport and kinesin motility but not vesicle-specific processive tracking with temporal persistence semantics."
    },
    {
      "claim_id": "ISS-004",
      "claim_text": "Microtubules serve as structural tracks (cytoskeletal architecture) that enable but do not constitute a separate temporally-scoped process concurrent with vesicle transport.",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Cytoskeletal structure; microtubule organization; distinction between structural capability and dynamic process",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        }
      ],
      "reason": "One source explicitly describes microtubules as tracks used by motors for cargo transport, supporting the structural-track role. However, no source addresses whether track provision is or is not a separate temporally-scoped process concurrent with vesicle transport; that distinction is not entailed."
    },
    {
      "claim_id": "ISS-005",
      "claim_text": "Vesicles are membrane-bound organelles that carry cargo and are moved within cells along cytoskeletal tracks including microtubules.",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Vesicle definition; membrane-bound cargo carriers; intracellular membrane trafficking",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        }
      ],
      "reason": "The source supports that organelles (which could include membrane-bound compartments) are transported along microtubules by motors. However, it does not explicitly define vesicles as membrane-bound cargo carriers or state that vesicles specifically are moved along cytoskeletal tracks. The membrane-bound definition and vesicle-specific movement are not entailed."
    },
    {
      "claim_id": "ISS-006",
      "claim_text": "Motor-protein-dependent vesicle transport along microtubules is supported by evidence naming motor proteins as causal agents, resolving the scope contradiction.",
      "entailment_status": "PARTIALLY_SUPPORTED",
      "biological_scope": "Motor-protein-dependent transport; kinesin/dynein; microtubule-based intracellular trafficking",
      "support": [
        {
          "evidence_id": "E_a7a76831c1a0",
          "location": "abstract",
          "quote": "Microtubules (MTs) are built from α-/β-tubulin dimers and used as tracks by kinesin and dynein motors to transport a variety of cargos, such as mRNAs, proteins, and organelles, within the cell."
        },
        {
          "evidence_id": "E_3717dae1f63f",
          "location": "abstract",
          "quote": "Tau weakly inhibits KIF5C motility, but strongly inhibits KIF1A."
        }
      ],
      "reason": "Sources name kinesin and dynein as motors that transport cargo along microtubules, and describe effects on KIF5C/KIF1A motility. However, they do not explicitly establish motor-protein-dependent vesicle transport specifically, nor do they resolve a scope contradiction about vesicles as the cargo. The claim is broader than what the excerpts directly entail."
    },
    {
      "claim_id": "ISS-007",
      "claim_text": "Kinesin motors generally drive anterograde (toward plus-end) transport and cytoplasmic dynein drives retrograde (toward minus-end) transport, with organism-specific details varying across eukaryotes.",
      "entailment_status": "INSUFFICIENT_EVIDENCE",
      "biological_scope": "Motor directionality; kinesin superfamily; cytoplasmic dynein; organism-specific variation in microtubule organization",
      "support": [],
      "reason": "No provided source excerpt states the directionality of kinesin (anterograde/plus-end) versus dynein (retrograde/minus-end), nor does any excerpt discuss organism-specific variation in motor directionality. The abstracts mention kinesin-1-dependent processes and anterograde axonal transport of mitochondria, but do not define directionality of kinesin versus dynein in general."
    },
    {
      "claim_id": "STATE_MODEL_MIGRATION",
      "claim_text": "Initial states require a vesicle, a microtubule track, and available motor proteins with ATP; vesicle position along the microtubule is the tracked property, and motor engagement is a required state producer.",
      "entailment_status": "INSUFFICIENT_EVIDENCE",
      "biological_scope": "State modeling of intracellular transport; initial conditions; motor engagement; vesicle position along microtubule",
      "support": [],
      "reason": "No provided source excerpt addresses state modeling, initial conditions requiring vesicles, microtubules, motor proteins, and ATP, tracking of vesicle position, or motor engagement as a state producer. The abstracts describe biological mechanisms but do not contain the formal state-model claims requested."
    }
  ],
  "decision": "INSUFFICIENT_EVIDENCE"
}
